from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    stack = []
    current_group = []

    for char in paren_string.replace(" ", ""):
        if char == '(':
            if len(stack) == 0 and current_group:
                result.append(''.join(current_group))
                current_group = []
            stack.append(char)
            current_group.append(char)
        elif char == ')':
            stack.pop()
            current_group.append(char)
            if len(stack) == 0:
                result.append(''.join(current_group))
                current_group = []

    if current_group:
        result.append(''.join(current_group))

    return result

